_LOCK = threading.RLock()
_CACHE: dict = {}
OUT = Path("/app/out")
ARTIFACT_NAMES = ("config.json", "report.json", "tool.zip", "profile_dev.json", "profile_prod.json",
                  "validation_report.json", "summary.json")
_SETPRIV = ["setpriv", "--reuid=nobody", "--regid=nogroup", "--clear-groups"]
_MAX_JSON = 64 * 1024 * 1024
_CALL_SECONDS = 450
_BUDGET_SECONDS = 2400
_T0 = time.monotonic()
HELDOUT_TIERS = (("tier_a", 51017, 0.05, "heldout"), ("tier_b", 62029, 0.05, "heldout"),
                 ("tier_c", 73031, 0.04, "boundary"))
CONV_TIERS = (("conv_1", 91019, "Site/Dune", "half"), ("conv_2", 85041, "Site/Dune", "closed"),
              ("conv_3", 93029, "Site/Ember", "half"), ("conv_4", 96043, "Site/Cobalt", "half"),
              ("conv_5", 92023, "Site/Brisk", "half"), ("conv_6", 98123, "Site/Brisk", "closed"),
              ("conv_7", 94031, "Site/Arden", "half"), ("conv_8", 99061, "Site/Arden", "closed"))


def _conv_of(name: str) -> dict:
    for tier, _, zone, window in CONV_TIERS:
        if tier == name:
            return {"hr": "zone:" + zone, "start": "requested", "window": window}
    raise KeyError(name)


def _cached(key, build):
    with _LOCK:
        if key not in _CACHE:
            try:
                _CACHE[key] = build()
            except Exception:
                _CACHE[key] = None
        return _CACHE[key]


def _read_json(path: Path):
    try:
        if path.is_symlink() or not path.is_file() or path.stat().st_size > _MAX_JSON:
            return None
        return json.loads(path.read_bytes().decode("utf-8"))
    except Exception:
        return None


def _artifact(name: str):
    return _read_json(OUT / name)


def _scratch(prefix: str) -> Path:
    path = Path(tempfile.mkdtemp(prefix=prefix))
    path.chmod(0o755)
    return path


def _open_tree(root: Path) -> None:
    for p in [root, *root.rglob("*")]:
        p.chmod(0o755 if p.is_dir() else 0o644)


def _shipped_dir() -> Path:
    def build():
        root = _scratch("warrant-shipped-")
        files = json.loads(zlib.decompress(base64.b64decode(SHIPPED_CORPUS)).decode("utf-8"))
        for name in SHIPPED_NAMES:
            (root / name).write_text(files.get(name, ""), encoding="utf-8")
        _open_tree(root)
        return root
    return _cached("shipped_dir", build)


def _expected_shipped():
    def build():
        root = _shipped_dir()
        cfg, profiles, audit, summary, _ = everything(root)
        summary = dict(summary, inputs=sorted(SHIPPED_NAMES), input_count=len(SHIPPED_NAMES))
        return cfg, profiles, audit, summary
    return _cached("expected_shipped", build)


def _tier(name: str) -> Path | None:
    def build_one():
        for tier, seed, scale, variant in HELDOUT_TIERS:
            if tier == name:
                root = _scratch(f"warrant-{tier}-")
                build(root, seed, scale, variant)
                _open_tree(root)
                return root
        if name == "tier_a_shuffled":
            src = _tier("tier_a")
            root = _scratch("warrant-shuffled-")
            shuffle_records(src, root, 4242)
            _open_tree(root)
            return root
        return None
    return _cached(("tier", name), build_one)


def _expected_tier(name: str):
    def build_one():
        root = _tier(name)
        cfg, profiles, audit, summary, _ = everything(root)
        names = sorted(p.name for p in root.iterdir() if p.is_file())
        return cfg, profiles, audit, dict(summary, inputs=names, input_count=len(names))
    return _cached(("expected", name), build_one)


def _conv_tier(name: str) -> Path | None:
    def build_one():
        for tier, seed, _, _ in CONV_TIERS:
            if tier == name:
                root = _scratch(f"warrant-{tier}-")
                build(root, seed, 0.05, "conv", _conv_of(name))
                _open_tree(root)
                return root
        return None
    return _cached(("tier", name), build_one)


def _expected_conv(name: str):
    def build_one():
        root = _conv_tier(name)
        cfg, profiles, audit, summary, _ = everything(root, _conv_of(name))
        return cfg, profiles
    return _cached(("expected", name), build_one)


def _conv_profile_match(tier: str, env: str) -> bool:
    got, exp = _run_all(_conv_tier(tier), tier), _expected_conv(tier)
    return _same(got[env], exp[1][env])


def _tool_dir() -> Path | None:
    def build_one():
        archive = OUT / "tool.zip"
        if archive.is_symlink() or not archive.is_file():
            return None
        root = _scratch("warrant-tool-")
        total = 0
        with zipfile.ZipFile(archive) as zf:
            for info in zf.infolist():
                rel = PurePosixPath(info.filename)
                mode = (info.external_attr >> 16) & 0xFFFF
                if rel.is_absolute() or ".." in rel.parts or "\\" in info.filename or stat.S_ISLNK(mode):
                    return None
                if info.is_dir():
                    continue
                total += info.file_size
                if total > 50 * 1024 * 1024:
                    return None
                dest = root / Path(*rel.parts)
                dest.parent.mkdir(parents=True, exist_ok=True)
                dest.write_bytes(zf.read(info))
        if not (root / "cli.py").is_file():
            return None
        _open_tree(root)
        return root
    return _cached("tool_dir", build_one)


def _invoke(args: list[str]) -> int | None:
    tool = _tool_dir()
    if tool is None:
        return None
    argv = [sys.executable, str(tool / "cli.py"), *args]
    if os.name == "posix" and os.geteuid() == 0 and shutil.which("setpriv"):
        argv = [*_SETPRIV, *argv]
    work = _scratch("warrant-run-")
    work.chmod(0o777)
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8", "HOME": str(work)}
    left = _BUDGET_SECONDS - (time.monotonic() - _T0)
    if left <= 1:
        return None
    try:
        proc = subprocess.Popen(argv, cwd=work, env=env, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE, start_new_session=True)
    except Exception:
        return None
    try:
        proc.communicate(timeout=min(_CALL_SECONDS, left))
        rc = proc.returncode
    except Exception:
        rc = None
    try:
        os.killpg(proc.pid, signal.SIGKILL)
    except (ProcessLookupError, PermissionError):
        pass
    if rc is None:
        try:
            proc.communicate(timeout=10)
        except Exception:
            pass
    return rc


def _run_all(data: Path, label: str) -> dict:
    """Run every subcommand of the delivered tool over one corpus; parsed outputs or None."""
    def build_one():
        out = _scratch(f"warrant-out-{label}-")
        out.chmod(0o777)
        cfg = out / "config.json"
        got = {"rc": {}}
        got["rc"]["resolve-config"] = _invoke(["resolve-config", "--data", str(data), "--out", str(cfg)])
        got["config"] = _read_json(cfg) if got["rc"]["resolve-config"] == 0 else None
        for profile in ("dev", "prod"):
            path = out / f"profile_{profile}.json"
            rc = _invoke(["compile", "--data", str(data), "--config", str(cfg), "--profile", profile, "--out", str(path)])
            got["rc"][profile] = rc
            got[profile] = _read_json(path) if rc == 0 else None
            got[profile + "_bytes"] = path.read_bytes() if rc == 0 and path.is_file() else None
        for sub, name in (("audit", "audit"), ("summarize", "summary")):
            path = out / f"{name}.json"
            rc = _invoke([sub, "--data", str(data), "--config", str(cfg), "--out", str(path)])
            got["rc"][sub] = rc
            got[name] = _read_json(path) if rc == 0 else None
        return got
    return _cached(("run", label), build_one)


def _same(a, b) -> bool:
    return a is not None and b is not None and json.dumps(a, sort_keys=True) == json.dumps(b, sort_keys=True)


def _rows(items):
    return sorted(json.dumps(x, sort_keys=True) for x in items) if isinstance(items, list) else None


def _audit_part(doc, part):
    return _rows(doc.get(part)) if isinstance(doc, dict) else None


def _sha(path: Path) -> str | None:
    try:
        if not path.is_file():
            return None
        return hashlib.sha256(path.read_bytes()).hexdigest()
    except OSError:
        return None


def _tree_digest(root: Path) -> str:
    h = hashlib.sha256()
    for p in sorted(root.rglob("*")):
        h.update(p.relative_to(root).as_posix().encode())
        if p.is_file():
            h.update(p.read_bytes())
    return h.hexdigest()


