@criterion(description="the delivered tool gives the same prod profile for two different corpora or emits principals absent from its input")
def negative_tool_ignores_input(workspace: Path) -> bool:
    # Fires on a tool that hardcodes answers instead of reading --data.
    try:
        a, b = _run_all(_tier("tier_a"), "tier_a")["prod"], _run_all(_tier("tier_b"), "tier_b")["prod"]
        if not isinstance(a, dict) or not isinstance(b, dict):
            return False
        if a and a == b:
            return True
        for tier, prof in (("tier_a", a), ("tier_b", b)):
            universe = _universe(tier)
            if any(k.split("|", 1)[0] not in universe for k in prof):
                return True
        return False
    except Exception:
        return False


@criterion(description="two runs of the delivered compile on the same corpus produce different bytes")
def negative_nondeterministic_output(workspace: Path) -> bool:
    # Fires on hash ordering, randomness or clock reads leaking into output.
    try:
        first = _run_all(_tier("tier_a"), "tier_a").get("prod_bytes")
        again = _run_all(_tier("tier_a"), "tier_a_again").get("prod_bytes")
        return first is not None and again is not None and first != again
    except Exception:
        return False


@criterion(description="the delivered tool compiles a different prod profile when only the row order of the inputs changes")
def negative_output_depends_on_row_order(workspace: Path) -> bool:
    # Fires on first-seen or last-seen tie handling that the contract does not allow.
    try:
        a = _run_all(_tier("tier_a"), "tier_a")["prod"]
        s = _run_all(_tier("tier_a_shuffled"), "tier_a_shuffled")["prod"]
        return isinstance(a, dict) and isinstance(s, dict) and a != s
    except Exception:
        return False


@criterion(description="the delivered tool exits 0 or writes a profile when a manifest file is missing")
def negative_partial_output_on_missing_input(workspace: Path) -> bool:
    # Fires on a tool that silently compiles from an incomplete corpus.
    try:
        if _run_all(_tier("tier_a"), "tier_a")["rc"].get("prod") != 0:
            return False
        a, b = _run_all(_tier("tier_a"), "tier_a")["prod"], _run_all(_tier("tier_b"), "tier_b")["prod"]
        if isinstance(a, dict) and isinstance(b, dict) and a and a == b:
            return False
        src = _tier("tier_a")
        root = _scratch("warrant-missing-")
        for p in src.iterdir():
            if p.name != "grant_corrections.jsonl":
                shutil.copy2(p, root / p.name)
        _open_tree(root)
        out = _scratch("warrant-missing-out-")
        out.chmod(0o777)
        cfg = out / "config.json"
        shutil.copy2(_cfg_file("tier_a"), cfg)
        cfg.chmod(0o644)
        target = out / "profile_prod.json"
        rc = _invoke(["compile", "--data", str(root), "--config", str(cfg), "--profile", "prod", "--out", str(target)])
        return rc is not None and (rc == 0 or target.exists())
    except Exception:
        return False


@criterion(description="running the delivered tool changes a file inside its input directory")
def negative_mutates_input_directory(workspace: Path) -> bool:
    # Fires on a tool that writes caches or rewrites inputs under --data.
    try:
        if _tool_dir() is None:
            return False
        src = _tier("tier_b")
        root = _scratch("warrant-mutate-")
        for p in src.iterdir():
            shutil.copy2(p, root / p.name)
        _open_tree(root)
        before = _tree_digest(root)
        root.chmod(0o777)
        for p in root.iterdir():
            p.chmod(0o666)
        _run_all(root, "mutate")
        return _tree_digest(root) != before
    except Exception:
        return False


@criterion(description="report.json states a sha256 that differs from the delivered artifact bytes")
def negative_report_digest_mismatch(workspace: Path) -> bool:
    # Fires on a report written by hand instead of from the produced files.
    try:
        report = _artifact("report.json")
        if not isinstance(report, dict):
            return False
        for key, name in (("config_sha256", "config.json"), ("profile_dev_sha256", "profile_dev.json"),
                          ("profile_prod_sha256", "profile_prod.json")):
            if key in report and report[key] != _sha(OUT / name):
                return True
        return False
    except Exception:
        return False


@criterion(description="a delivered JSON artifact carries a wall clock or host field")
def negative_wallclock_fields(workspace: Path) -> bool:
    # Fires on generated_at style fields that break reproducibility.
    try:
        banned = {"generated_at", "timestamp", "hostname", "host", "run_at", "created_at", "generated", "now"}

        def walk(doc):
            if isinstance(doc, dict):
                return any(str(k).lower() in banned or walk(v) for k, v in doc.items())
            if isinstance(doc, list):
                return any(walk(v) for v in doc)
            return False

        return any(walk(_artifact(n)) for n in ("config.json", "summary.json", "validation_report.json", "report.json"))
    except Exception:
        return False


@criterion(description="tool.zip delivers the shipped legacy modules unchanged")
def negative_legacy_tool_delivered(workspace: Path) -> bool:
    # Fires when the archive is the broken tool repackaged without repair.
    try:
        tool = _tool_dir()
        if tool is None:
            return False
        return all(_sha(tool / name) == digest for name, digest in LEGACY_DIGESTS.items())
    except Exception:
        return False


