def _universe(tier: str) -> set:
    def build_one():
        D = load(_tier(tier))
        cfg, _, _ = settle_config(D)
        return set(World(D, cfg).people)
    return _cached(("universe", tier), build_one)


def _cfg_file(tier: str) -> Path:
    def build_one():
        root = _scratch("warrant-cfg-")
        cfg = _expected_tier(tier)[0]
        path = root / "config.json"
        path.write_text(json.dumps(cfg, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        _open_tree(root)
        return path
    return _cached(("cfg", tier), build_one)


